random.seed(1234)

def vals(field, low, high):
    return sorted(set(int(x) for x in field.split(','))) if field != '*' else list(range(low, high+1))

# Use simple expressions whose semantics are easy to mirror.
minutes = ['*', '0', '15', '0,30', '*/20', '5/20', '10-40/10']
hours = ['*', '0', '12', '0,23', '*/6']
doms = ['*', '1', '15', '31', '1,15', '*/10']
months = ['*', '1', '2', '1,6', '*/3']
dows = ['*', '0', '1', '5', '7', '1-5', '0-2', '6-7', '*/2']

def expand(field, low, high, names=None):
    out = set()
    for item in field.split(','):
        if '/' in item:
            base, step = item.split('/'); step=int(step)
            if base == '*': a,b=low,high
            elif '-' in base: a,b=map(int,base.split('-'))
            else: a,b=int(base),high
            out.update(range(a,b+1,step))
        elif item == '*': out.update(range(low,high+1))
        elif '-' in item:
            a,b=map(int,item.split('-')); out.update(range(a,b+1))
        else: out.add(int(item))
    return out

def pyweekday(cron_dow):
    return (cron_dow + 6) % 7

def matches(dt, expr):
    f = expr.split()
    mi, ho, dom, mo, dow = f
    return (dt.minute in expand(mi,0,59) and dt.hour in expand(ho,0,23)
            and dt.month in expand(mo,1,12)
            and ((dt.day in expand(dom,1,31)) or (dt.weekday() in {pyweekday(x) for x in expand(dow,0,7)}))
            and (dom != '*' and dow != '*' or True))

def ref(expr, after):
    # strict after, whole-minute candidates
    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    if after.second or after.microsecond:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    else:
        start = after + timedelta(minutes=1)
    f = expr.split()
    domrest = f[2] != '*'; dowrest = f[4] != '*'
    for i in range(60*24*800):
        dt = start + timedelta(minutes=i)
        if dt.month not in expand(f[3],1,12): continue
        dm = dt.day in expand(f[2],1,31)
        dw = dt.weekday() in {pyweekday(x) for x in expand(f[4],0,7)}
        ok = (dm or dw) if (domrest and dowrest) else (dm and dw)
        if ok and dt.minute in expand(f[0],0,59) and dt.hour in expand(f[1],0,23):
            return dt
    return None

for n in range(300):
